/* Deel Quick — DevTools snippet build. Generated by tools/make-snippet.sh — do not edit by hand.
   Paste into DevTools Console (or Sources > Snippets) on a logged-in Deel page, then run:
   __deelQuick.run({ intent: 'what to improve', delayMs: 0, downscaleImages: false }) */
/*
 * Deel Quick — capture utilities.
 * All capture files attach to window.__deelQuick so they work both when
 * injected by the extension (chrome.scripting.executeScript, ordered files)
 * and when pasted as a DevTools snippet (see snippet/ and tools/make-snippet.sh).
 */
(() => {
  const dq = (window.__deelQuick = window.__deelQuick || {});

  // ---- Environment ---------------------------------------------------------

  dq.isExtension = !!(typeof chrome !== 'undefined' && chrome.runtime && chrome.runtime.id);

  // ---- Progress reporting --------------------------------------------------

  dq.progress = (phase, detail) => {
    const msg = { type: 'dq-progress', phase, detail: detail || '' };
    if (dq.isExtension) {
      try { chrome.runtime.sendMessage(msg); } catch (_) { /* popup closed — fine */ }
    }
    // Always mirror to the console so the DevTools-snippet path has feedback.
    console.log(`[deel-quick] ${phase}${detail ? ' — ' + detail : ''}`);
  };

  // ---- Byte ledger ---------------------------------------------------------
  // Tracks payload by category so the 16MB artifact budget is visible per lever.

  dq.newLedger = () => ({ dom: 0, css: 0, fonts: 0, images: 0, canvas: 0 });

  dq.ledgerTotal = (ledger) => Object.values(ledger).reduce((a, b) => a + b, 0);

  dq.fmtBytes = (n) => {
    if (n >= 1024 * 1024) return (n / (1024 * 1024)).toFixed(1) + 'MB';
    if (n >= 1024) return Math.round(n / 1024) + 'KB';
    return n + 'B';
  };

  // ---- Fetch with fallback chain ------------------------------------------
  // 1. Page-context fetch (has the user's cookies, subject to CORS/page CSP).
  // 2. Extension background relay (host permissions bypass CORS on Deel CDNs).
  // Returns { bytes: Uint8Array, contentType } or null (caller records a warning).

  dq.fetchResource = async (url) => {
    try {
      const res = await fetch(url, { credentials: 'include', cache: 'force-cache' });
      if (res.ok) {
        const buf = new Uint8Array(await res.arrayBuffer());
        return { bytes: buf, contentType: res.headers.get('content-type') || '' };
      }
    } catch (_) { /* fall through to relay */ }

    if (dq.isExtension) {
      try {
        const reply = await chrome.runtime.sendMessage({ type: 'dq-fetch', url });
        if (reply && reply.ok) {
          return { bytes: dq.base64ToBytes(reply.base64), contentType: reply.contentType || '' };
        }
      } catch (_) { /* relay unavailable */ }
    }
    return null;
  };

  // Single-flight cache so each unique URL is fetched once per capture.
  dq.resourceCache = new Map();
  dq.fetchResourceCached = (url) => {
    if (!dq.resourceCache.has(url)) dq.resourceCache.set(url, dq.fetchResource(url));
    return dq.resourceCache.get(url);
  };

  // ---- Encoding helpers ----------------------------------------------------

  dq.bytesToBase64 = (bytes) => {
    let binary = '';
    const CHUNK = 0x8000;
    for (let i = 0; i < bytes.length; i += CHUNK) {
      binary += String.fromCharCode.apply(null, bytes.subarray(i, i + CHUNK));
    }
    return btoa(binary);
  };

  dq.base64ToBytes = (b64) => {
    const binary = atob(b64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    return bytes;
  };

  const MIME_BY_EXT = {
    woff2: 'font/woff2', woff: 'font/woff', ttf: 'font/ttf', otf: 'font/otf',
    png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', gif: 'image/gif',
    webp: 'image/webp', svg: 'image/svg+xml', ico: 'image/x-icon', avif: 'image/avif',
  };

  dq.guessMime = (url, contentType) => {
    if (contentType && contentType !== 'application/octet-stream') {
      return contentType.split(';')[0].trim();
    }
    const ext = (url.split(/[?#]/)[0].split('.').pop() || '').toLowerCase();
    return MIME_BY_EXT[ext] || 'application/octet-stream';
  };

  dq.isFontMime = (mime) => mime.startsWith('font/') || mime.includes('font-woff') || mime.includes('opentype');

  dq.toDataUri = (bytes, mime) => `data:${mime};base64,${dq.bytesToBase64(bytes)}`;

  // ---- Image downscaling ---------------------------------------------------
  // Re-encodes a data URI image to fit maxWidth (JPEG q0.8). Skips SVG and
  // anything already small. Used by the size-budget pass on images and canvas
  // snapshots.

  dq.downscaleDataUri = (dataUri, maxWidth = 1200, quality = 0.8) =>
    new Promise((resolve) => {
      if (dataUri.startsWith('data:image/svg') || dataUri.length < 50 * 1024) {
        resolve(dataUri);
        return;
      }
      const img = new Image();
      img.onload = () => {
        if (img.naturalWidth <= maxWidth) { resolve(dataUri); return; }
        const scale = maxWidth / img.naturalWidth;
        const canvas = document.createElement('canvas');
        canvas.width = maxWidth;
        canvas.height = Math.round(img.naturalHeight * scale);
        canvas.getContext('2d').drawImage(img, 0, 0, canvas.width, canvas.height);
        try {
          const out = canvas.toDataURL('image/jpeg', quality);
          resolve(out.length < dataUri.length ? out : dataUri);
        } catch (_) { resolve(dataUri); }
      };
      img.onerror = () => resolve(dataUri);
      img.src = dataUri;
    });

  // ---- Misc ----------------------------------------------------------------

  dq.slugify = (text) =>
    (text || 'screen')
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '')
      .slice(0, 60) || 'screen';

  dq.escapeComment = (text) => String(text || '').replace(/--/g, '—');
})();
/*
 * Deel Quick — DOM snapshot (capture phases 1–2).
 * Phase 1 stamps live runtime state (input values, canvas pixels, shadow roots)
 * onto elements via data-dq-* markers, because cloneNode() copies attributes,
 * not runtime properties.
 * Phase 2 deep-clones the document, applies the stamped state, and prunes
 * everything a static prototype must not carry (scripts, handlers, CSP metas).
 */
(() => {
  const dq = window.__deelQuick;

  const STATE_ATTR = 'data-dq-i';

  // ---- Phase 1: annotate live state ----------------------------------------

  dq.annotateLiveState = () => {
    const state = new Map(); // index -> {kind, ...payload}
    let nextIndex = 0;
    const stamp = (el, entry) => {
      el.setAttribute(STATE_ATTR, String(nextIndex));
      state.set(String(nextIndex), entry);
      nextIndex++;
    };

    document.querySelectorAll('input').forEach((el) => {
      if (el.type === 'checkbox' || el.type === 'radio') {
        stamp(el, { kind: 'checked', checked: el.checked });
      } else if (el.type !== 'password') {
        stamp(el, { kind: 'value', value: el.value });
      }
    });
    document.querySelectorAll('textarea').forEach((el) => stamp(el, { kind: 'text', value: el.value }));
    document.querySelectorAll('select').forEach((el) => stamp(el, { kind: 'select', index: el.selectedIndex }));

    // Images: record the resolved current source so srcset never re-resolves
    // against the network in the prototype.
    document.querySelectorAll('img').forEach((el) => {
      const src = el.currentSrc || el.src;
      if (src) stamp(el, { kind: 'img', src });
    });

    // Canvas → PNG snapshot (charts). Tainted canvases throw; those become
    // sized placeholders and a report entry.
    document.querySelectorAll('canvas').forEach((el) => {
      const rect = el.getBoundingClientRect();
      try {
        stamp(el, { kind: 'canvas', dataUri: el.toDataURL('image/png'), w: rect.width, h: rect.height });
      } catch (_) {
        stamp(el, { kind: 'canvas-tainted', w: rect.width, h: rect.height });
      }
    });

    // Shadow roots: serialize now (from the live tree — clones drop them).
    const shadowHosts = [];
    const walker = document.createTreeWalker(document.documentElement, NodeFilter.SHOW_ELEMENT);
    for (let el = walker.currentNode; el; el = walker.nextNode()) {
      if (el.shadowRoot) shadowHosts.push(el);
    }
    shadowHosts.forEach((el) => {
      let css = '';
      try {
        (el.shadowRoot.adoptedStyleSheets || []).forEach((sheet) => {
          for (const rule of sheet.cssRules) css += rule.cssText + '\n';
        });
      } catch (_) { /* ignore unreadable adopted sheets */ }
      stamp(el, { kind: 'shadow', html: el.shadowRoot.innerHTML, css });
    });

    return state;
  };

  dq.clearLiveAnnotations = () => {
    document.querySelectorAll(`[${STATE_ATTR}]`).forEach((el) => el.removeAttribute(STATE_ATTR));
  };

  // ---- Phase 2: clone, apply state, prune -----------------------------------

  dq.buildClone = (state, report) => {
    const clone = document.documentElement.cloneNode(true);

    // Apply stamped runtime state to the clone.
    clone.querySelectorAll(`[${STATE_ATTR}]`).forEach((el) => {
      const entry = state.get(el.getAttribute(STATE_ATTR));
      el.removeAttribute(STATE_ATTR);
      if (!entry) return;
      switch (entry.kind) {
        case 'value':
          el.setAttribute('value', entry.value);
          break;
        case 'checked':
          if (entry.checked) el.setAttribute('checked', '');
          else el.removeAttribute('checked');
          break;
        case 'text':
          el.textContent = entry.value;
          break;
        case 'select':
          Array.from(el.options || []).forEach((opt, i) => {
            if (i === entry.index) opt.setAttribute('selected', '');
            else opt.removeAttribute('selected');
          });
          break;
        case 'img':
          el.setAttribute('src', entry.src);
          el.removeAttribute('srcset');
          el.removeAttribute('sizes');
          break;
        case 'canvas': {
          const img = document.createElement('img');
          img.src = entry.dataUri;
          img.setAttribute('data-dq-canvas', '');
          img.style.width = entry.w + 'px';
          img.style.height = entry.h + 'px';
          if (el.className) img.className = el.className;
          el.replaceWith(img);
          break;
        }
        case 'canvas-tainted': {
          const ph = document.createElement('div');
          ph.setAttribute('data-dq-canvas-placeholder', '');
          ph.style.cssText = `width:${entry.w}px;height:${entry.h}px;background:#e5e7eb;display:flex;align-items:center;justify-content:center;color:#6b7280;font:12px sans-serif;`;
          ph.textContent = 'canvas (could not snapshot)';
          el.replaceWith(ph);
          report.warnings.push('1 canvas was tainted and became a placeholder');
          break;
        }
        case 'shadow': {
          const tpl = document.createElement('template');
          tpl.setAttribute('shadowrootmode', 'open');
          tpl.innerHTML = (entry.css ? `<style>${entry.css}</style>` : '') + entry.html;
          el.prepend(tpl);
          break;
        }
      }
    });

    // Prune: nothing executable or network-reaching survives.
    clone.querySelectorAll('script, noscript').forEach((el) => el.remove());
    clone
      .querySelectorAll('link[rel="preload"], link[rel="prefetch"], link[rel="modulepreload"], link[rel="manifest"], link[rel="dns-prefetch"], link[rel="preconnect"]')
      .forEach((el) => el.remove());
    clone.querySelectorAll('meta[http-equiv]').forEach((el) => {
      const v = (el.getAttribute('http-equiv') || '').toLowerCase();
      if (v === 'content-security-policy' || v === 'refresh') el.remove();
    });
    clone.querySelectorAll('base').forEach((el) => el.remove());

    // Inline event handlers and javascript: URLs.
    const all = clone.querySelectorAll('*');
    all.forEach((el) => {
      for (const attr of Array.from(el.attributes)) {
        if (attr.name.startsWith('on')) el.removeAttribute(attr.name);
      }
      const href = el.getAttribute && el.getAttribute('href');
      if (href && href.trim().toLowerCase().startsWith('javascript:')) el.setAttribute('href', '#');
    });

    // Links: neutralize navigation, preserve the original target for the
    // quick-iterate skill (multi-screen linking rewrites data-orig-href).
    clone.querySelectorAll('a[href]').forEach((el) => {
      const href = el.getAttribute('href');
      if (href && href !== '#' && !href.startsWith('data:')) {
        try {
          el.setAttribute('data-orig-href', new URL(href, location.href).href);
        } catch (_) {
          el.setAttribute('data-orig-href', href);
        }
        el.setAttribute('href', '#');
      }
    });

    // Iframes → sized, labeled placeholders.
    clone.querySelectorAll('iframe').forEach((el) => {
      let host = 'iframe';
      try { host = new URL(el.getAttribute('src') || '', location.href).hostname || 'iframe'; } catch (_) { /* keep default */ }
      const ph = document.createElement('div');
      const w = el.getAttribute('width') || el.style.width || '100%';
      const h = el.getAttribute('height') || el.style.height || '200px';
      ph.setAttribute('data-dq-iframe', host);
      ph.style.cssText = `width:${w};height:${h};background:#f3f4f6;border:1px dashed #d1d5db;display:flex;align-items:center;justify-content:center;color:#6b7280;font:12px sans-serif;`;
      ph.textContent = `iframe: ${host}`;
      el.replaceWith(ph);
      report.warnings.push(`iframe placeholdered: ${host}`);
    });

    // Stylesheet <link>s go away — css-inline.js re-emits them as <style>.
    clone.querySelectorAll('link[rel~="stylesheet"]').forEach((el) => el.remove());
    clone.querySelectorAll('style').forEach((el) => el.remove());

    return clone;
  };
})();
/*
 * Deel Quick — stylesheet inlining via CSSOM (capture phase 3).
 * Serializing from CSSOM (not the raw text) matters for React apps: CSS-in-JS
 * libraries insert rules directly into empty <style> tags, so cssRules is the
 * only complete source of truth. Cross-origin sheets fall back to fetching the
 * href (page context → background relay). Every sheet's relative url(...) is
 * resolved against that sheet's own base before concatenation.
 */
(() => {
  const dq = window.__deelQuick;

  const resolveUrls = (cssText, baseHref) =>
    cssText.replace(/url\(\s*(['"]?)([^'")]+)\1\s*\)/g, (match, quote, ref) => {
      const trimmed = ref.trim();
      if (trimmed.startsWith('data:') || trimmed.startsWith('#') || trimmed.startsWith('blob:')) return match;
      try {
        return `url("${new URL(trimmed, baseHref).href}")`;
      } catch (_) {
        return match;
      }
    });

  const serializeRules = (rules, baseHref, out) => {
    for (const rule of rules) {
      if (rule.type === CSSRule.IMPORT_RULE && rule.styleSheet) {
        try {
          serializeRules(rule.styleSheet.cssRules, rule.styleSheet.href || baseHref, out);
          continue;
        } catch (_) { /* cross-origin import — fall through to cssText (kept as-is, reported) */ }
      }
      out.push(resolveUrls(rule.cssText, baseHref));
    }
  };

  const readSheet = async (sheet, report) => {
    const baseHref = sheet.href || location.href;
    try {
      const out = [];
      serializeRules(sheet.cssRules, baseHref, out);
      return out.join('\n');
    } catch (_) {
      // SecurityError: cross-origin without CORS. Fetch the raw text instead.
      if (!sheet.href) return '';
      const res = await dq.fetchResourceCached(sheet.href);
      if (!res) {
        report.warnings.push(`stylesheet unreadable, skipped: ${sheet.href}`);
        return '';
      }
      let text = new TextDecoder().decode(res.bytes);
      // Recursively pull in @imports from fetched text.
      const importRe = /@import\s+(?:url\()?\s*['"]?([^'")\s;]+)['"]?\)?[^;]*;/g;
      const imports = [...text.matchAll(importRe)];
      for (const m of imports) {
        let importedText = '';
        try {
          const importUrl = new URL(m[1], sheet.href).href;
          const sub = await dq.fetchResourceCached(importUrl);
          if (sub) importedText = resolveUrls(new TextDecoder().decode(sub.bytes), importUrl);
          else report.warnings.push(`@import unreadable, skipped: ${importUrl}`);
        } catch (_) { /* leave importedText empty */ }
        text = text.replace(m[0], importedText);
      }
      return resolveUrls(text, sheet.href);
    }
  };

  // ---- Used-font filtering ---------------------------------------------------
  // The single biggest 16MB lever: only @font-face rules whose family+weight
  // were actually loaded by the page survive.

  const loadedFontKeys = () => {
    const keys = new Set();
    try {
      document.fonts.forEach((face) => {
        if (face.status === 'loaded') {
          const family = face.family.replace(/['"]/g, '').toLowerCase().trim();
          keys.add(`${family}|${face.weight}|${face.style}`);
          keys.add(family); // family-level fallback for range weights
        }
      });
    } catch (_) { /* document.fonts unavailable — keep all fonts */ }
    return keys;
  };

  const weightMatches = (faceWeight, loadedKeys, family) => {
    // face weight can be "400", "bold", or a range "100 900".
    for (const key of loadedKeys) {
      if (!key.includes('|')) continue;
      const [fam, weight] = key.split('|');
      if (fam !== family) continue;
      const w = parseInt(weight, 10) || (weight === 'bold' ? 700 : 400);
      const parts = String(faceWeight || 'normal').trim().split(/\s+/);
      const lo = parseInt(parts[0], 10) || (parts[0] === 'bold' ? 700 : 400);
      const hi = parts[1] ? parseInt(parts[1], 10) || lo : lo;
      if (w >= lo && w <= hi) return true;
    }
    return false;
  };

  dq.filterUnusedFontFaces = (cssText, report) => {
    const keys = loadedFontKeys();
    if (keys.size === 0) return cssText; // can't tell — keep everything
    let dropped = 0;
    const result = cssText.replace(/@font-face\s*\{[^}]*\}/g, (block) => {
      const famMatch = block.match(/font-family\s*:\s*['"]?([^'";}]+)['"]?/i);
      if (!famMatch) return block;
      const family = famMatch[1].toLowerCase().trim();
      if (!keys.has(family)) { dropped++; return ''; }
      const weightMatch = block.match(/font-weight\s*:\s*([^;}]+)/i);
      const faceWeight = weightMatch ? weightMatch[1] : 'normal';
      if (weightMatches(faceWeight, keys, family)) return block;
      dropped++;
      return '';
    });
    if (dropped > 0) report.notes.push(`${dropped} unused @font-face rules dropped`);
    return result;
  };

  // ---- Entry point -----------------------------------------------------------
  // Returns a single <style> payload string (all sheets, original order).

  dq.collectCss = async (report) => {
    const chunks = [];
    const sheets = [...document.styleSheets, ...(document.adoptedStyleSheets || [])];
    for (const sheet of sheets) {
      if (sheet.disabled) continue;
      if (sheet.media && sheet.media.mediaText === 'print') continue;
      const css = await readSheet(sheet, report);
      if (!css.trim()) continue;
      const media = sheet.media && sheet.media.mediaText && sheet.media.mediaText !== 'all'
        ? sheet.media.mediaText : null;
      chunks.push({
        source: sheet.href || 'inline',
        css: media ? `@media ${media} {\n${css}\n}` : css,
      });
    }
    return chunks;
  };
})();
/*
 * Deel Quick — asset inlining and size budget (capture phases 4–5).
 * Everything the artifact CSP would block (any http(s) resource) becomes a
 * data: URI: <img> sources, CSS url(...) references (fonts, background
 * images), external SVG sprites, and the favicon. A byte ledger tracks each
 * category against the 16MB artifact ceiling.
 */
(() => {
  const dq = window.__deelQuick;

  const isInlineable = (url) =>
    url && !url.startsWith('data:') && !url.startsWith('#') && !url.startsWith('blob:') &&
    (url.startsWith('http://') || url.startsWith('https://'));

  const fetchAsDataUri = async (url, report) => {
    const res = await dq.fetchResourceCached(url);
    if (!res) {
      report.warnings.push(`asset unreachable, left as-is: ${url.slice(0, 120)}`);
      return null;
    }
    const mime = dq.guessMime(url, res.contentType);
    return { dataUri: dq.toDataUri(res.bytes, mime), mime, size: res.bytes.length };
  };

  // blob: URLs can only be materialized from the live page context.
  const blobToDataUri = (url) =>
    fetch(url)
      .then((r) => r.blob())
      .then(
        (blob) =>
          new Promise((resolve) => {
            const reader = new FileReader();
            reader.onload = () => resolve(reader.result);
            reader.onerror = () => resolve(null);
            reader.readAsDataURL(blob);
          })
      )
      .catch(() => null);

  // ---- <img> and other element-level assets ---------------------------------

  dq.inlineElementAssets = async (clone, ledger, report, opts) => {
    const imgs = Array.from(clone.querySelectorAll('img'));
    for (const img of imgs) {
      const src = img.getAttribute('src') || '';
      if (src.startsWith('blob:')) {
        const dataUri = await blobToDataUri(src);
        if (dataUri) { img.setAttribute('src', dataUri); ledger.images += dataUri.length; }
        else report.warnings.push('a blob: image could not be materialized');
        continue;
      }
      if (!isInlineable(src)) {
        if (src.startsWith('data:')) ledger[img.hasAttribute('data-dq-canvas') ? 'canvas' : 'images'] += src.length;
        continue;
      }
      const asset = await fetchAsDataUri(new URL(src, location.href).href, report);
      if (!asset) continue;
      let dataUri = asset.dataUri;
      if (opts.downscaleImages) dataUri = await dq.downscaleDataUri(dataUri);
      img.setAttribute('src', dataUri);
      img.removeAttribute('srcset');
      img.removeAttribute('sizes');
      img.removeAttribute('loading');
      ledger.images += dataUri.length;
    }

    // Inline style="background-image: url(...)" attributes.
    for (const el of clone.querySelectorAll('[style*="url("]')) {
      const style = el.getAttribute('style');
      const newStyle = await inlineCssUrls(style, location.href, ledger, report, opts);
      el.setAttribute('style', newStyle);
    }

    // External SVG sprites: <use href="https://cdn/sprite.svg#icon">.
    const uses = Array.from(clone.querySelectorAll('use')).filter((u) => {
      const href = u.getAttribute('href') || u.getAttribute('xlink:href') || '';
      return isInlineable(href.split('#')[0]);
    });
    const sprites = new Map(); // spriteUrl -> hidden container id
    for (const use of uses) {
      const href = use.getAttribute('href') || use.getAttribute('xlink:href');
      const [spriteUrl, fragment] = href.split('#');
      const abs = new URL(spriteUrl, location.href).href;
      if (!sprites.has(abs)) {
        const res = await dq.fetchResourceCached(abs);
        if (!res) {
          report.warnings.push(`svg sprite unreachable: ${abs}`);
          sprites.set(abs, null);
        } else {
          const holder = document.createElement('div');
          holder.style.display = 'none';
          holder.setAttribute('data-dq-sprite', abs);
          holder.innerHTML = new TextDecoder().decode(res.bytes);
          clone.querySelector('body').prepend(holder);
          ledger.images += res.bytes.length;
          sprites.set(abs, holder);
        }
      }
      if (sprites.get(abs)) {
        use.setAttribute('href', '#' + fragment);
        use.removeAttribute('xlink:href');
      }
    }

    // Favicon: replace all icon links with one inlined icon (nice artifact touch).
    const iconLink = clone.querySelector('link[rel~="icon"]');
    clone.querySelectorAll('link[rel~="icon"], link[rel="apple-touch-icon"]').forEach((el, i) => {
      if (el !== iconLink) el.remove();
    });
    if (iconLink && isInlineable(iconLink.getAttribute('href'))) {
      const asset = await fetchAsDataUri(new URL(iconLink.getAttribute('href'), location.href).href, report);
      if (asset) { iconLink.setAttribute('href', asset.dataUri); ledger.images += asset.dataUri.length; }
      else iconLink.remove();
    }
  };

  // ---- CSS url(...) inlining -------------------------------------------------

  const CSS_URL_RE = /url\(\s*(['"]?)(https?:\/\/[^'")]+)\1\s*\)/g;

  const inlineCssUrls = async (cssText, baseHref, ledger, report, opts) => {
    const refs = [...new Set([...cssText.matchAll(CSS_URL_RE)].map((m) => m[2]))];
    for (const url of refs) {
      const asset = await fetchAsDataUri(url, report);
      if (!asset) continue;
      let dataUri = asset.dataUri;
      const isFont = dq.isFontMime(asset.mime);
      if (!isFont && opts.downscaleImages) dataUri = await dq.downscaleDataUri(dataUri);
      ledger[isFont ? 'fonts' : 'images'] += dataUri.length;
      cssText = cssText.split(`url("${url}")`).join(`url("${dataUri}")`)
        .split(`url('${url}')`).join(`url("${dataUri}")`)
        .split(`url(${url})`).join(`url("${dataUri}")`);
    }
    return cssText;
  };

  dq.inlineCssAssets = async (cssChunks, ledger, report, opts) => {
    for (const chunk of cssChunks) {
      // Count rule text before inlining so data-URI bytes land only in the
      // fonts/images categories, not in css as well.
      ledger.css += chunk.css.length;
      chunk.css = await inlineCssUrls(chunk.css, chunk.source, ledger, report, opts);
    }
  };
})();
/*
 * Deel Quick — capture orchestrator (phase 6 + entry point).
 * window.__deelQuick.run(opts) drives the whole pipeline and hands the
 * finished file to the browser as a download. Works identically when injected
 * by the extension or pasted as a DevTools snippet.
 *
 * opts: {
 *   intent:           string  — "what do you want to improve?" (embedded in
 *                               the metadata comment)
 *   delayMs:          number  — wait before capturing (grab hover/menu state)
 *   downscaleImages:  boolean — re-encode large raster images (size budget)
 * }
 */
(() => {
  const dq = window.__deelQuick;

  const WARN_BYTES = 10 * 1024 * 1024;  // 10MB — warn
  const FLAG_BYTES = 14 * 1024 * 1024;  // 14MB — headroom under the 16MB artifact ceiling

  const buildMetadataComment = (report, opts) => {
    const L = report.ledger;
    const lines = [
      'deel-quick capture v0.1.0',
      `source: ${dq.escapeComment(location.href)}`,
      `title: ${dq.escapeComment(document.title)}`,
      `captured: ${new Date().toISOString()}`,
      `viewport: ${window.innerWidth}x${window.innerHeight}`,
      `size: dom ${dq.fmtBytes(L.dom)} / css ${dq.fmtBytes(L.css)} / fonts ${dq.fmtBytes(L.fonts)} / images ${dq.fmtBytes(L.images)} / canvas ${dq.fmtBytes(L.canvas)} = ${dq.fmtBytes(dq.ledgerTotal(L))}`,
    ];
    if (opts.intent) lines.push(`improvement-intent: ${dq.escapeComment(opts.intent)}`);
    if (report.warnings.length) lines.push(`warnings: ${dq.escapeComment(report.warnings.join(' | '))}`);
    if (report.notes.length) lines.push(`notes: ${dq.escapeComment(report.notes.join(' | '))}`);
    lines.push('changelog:');
    return `<!--\n  ${lines.join('\n  ')}\n-->`;
  };

  const download = (html, filename) => {
    const blob = new Blob([html], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 10_000);
  };

  dq.run = async (opts = {}) => {
    const report = { warnings: [], notes: [], ledger: dq.newLedger() };
    dq.resourceCache.clear();

    try {
      if (opts.delayMs) {
        dq.progress('waiting', `${opts.delayMs / 1000}s — set up the UI state you want captured`);
        await new Promise((r) => setTimeout(r, opts.delayMs));
      }

      dq.progress('snapshot', 'annotating live state and cloning the DOM');
      const state = dq.annotateLiveState();
      let clone;
      try {
        clone = dq.buildClone(state, report);
      } finally {
        dq.clearLiveAnnotations();
      }

      dq.progress('styles', 'serializing stylesheets via CSSOM');
      const cssChunks = await dq.collectCss(report);

      dq.progress('fonts', 'dropping unused @font-face rules');
      for (const chunk of cssChunks) {
        chunk.css = dq.filterUnusedFontFaces(chunk.css, report);
      }

      dq.progress('assets', 'inlining images, fonts, sprites as data: URIs');
      await dq.inlineCssAssets(cssChunks, report.ledger, report, opts);
      await dq.inlineElementAssets(clone, report.ledger, report, opts);

      dq.progress('assemble', 'writing the standalone HTML file');
      const head = clone.querySelector('head') || clone;
      for (const chunk of cssChunks) {
        const style = document.createElement('style');
        style.setAttribute('data-dq-source', chunk.source);
        style.textContent = chunk.css;
        head.appendChild(style);
      }

      const bodyHtml = clone.outerHTML;
      report.ledger.dom = bodyHtml.length - dq.ledgerTotal(report.ledger);
      if (report.ledger.dom < 0) report.ledger.dom = 0;

      const total = dq.ledgerTotal(report.ledger);
      if (total > FLAG_BYTES) {
        report.warnings.push(
          `capture is ${dq.fmtBytes(total)} — OVER the 14MB artifact budget; re-capture with image downscaling or trim per the size playbook`
        );
      } else if (total > WARN_BYTES) {
        report.warnings.push(`capture is ${dq.fmtBytes(total)} — approaching the 14MB artifact budget`);
      }

      const html = `<!doctype html>\n${buildMetadataComment(report, opts)}\n${bodyHtml}`;

      const slug = dq.slugify(document.title || location.pathname);
      const date = new Date().toISOString().slice(0, 10);
      const filename = `deel-${slug}--${date}-capture.html`;
      download(html, filename);

      const result = {
        type: 'dq-done',
        filename,
        totalBytes: html.length,
        ledger: report.ledger,
        warnings: report.warnings,
        notes: report.notes,
      };
      dq.progress('done', `${filename} (${dq.fmtBytes(html.length)})`);
      if (dq.isExtension) {
        try { chrome.runtime.sendMessage(result); } catch (_) { /* popup closed */ }
      }
      console.log('[deel-quick] capture report', result);
      return result;
    } catch (err) {
      const failure = { type: 'dq-error', message: String(err && err.message || err) };
      if (dq.isExtension) {
        try { chrome.runtime.sendMessage(failure); } catch (_) { /* popup closed */ }
      }
      console.error('[deel-quick] capture failed', err);
      dq.clearLiveAnnotations();
      throw err;
    }
  };
})();
console.log('[deel-quick] loaded — run __deelQuick.run({intent: "..."}) to capture this page');
